  end

  # slg: todo/laws.slg:10:5 todo.laws.numbers_below_next law.run
  def test_numbers_below_next
    Runtime::Testing.runs do |gen|
      prefix = gen.list(Runtime::Testing::PREFIX_MAX) { App::Events.any(gen) }
      events = Array.new(Runtime::Testing::TRACE_LENGTH) { App::Events.one_of(gen, [:add, :done, :reopen, :rename, :remove, :clear]) }
